}
var mu sync.RWMutex
var state *State
var wal *os.File
var dataDir = "../data"
var defaultImage []byte
var defaultHash string

func newState()*State {return &State{Users:map[int64]*StoredUser{},Names:map[string]int64{},Streams:map[int64]*StreamData{},ByUser:map[int64][]int64{},ByTag:map[int64][]int64{},Tags:map[int64]Tag{},Comments:map[int64]LivecommentModel{},Reactions:map[int64]ReactionModel{},Reports:map[int64]LivecommentReportModel{}}}
func hashImage(b []byte)string{return fmt.Sprintf("%x",sha256.Sum256(b))}
func max(a,b int64)int64 {if a>b{return a};return b}
func(s *State) apply(e Event) {
 switch e.Kind {
 case "user":
  u:=e.User;s.Users[u.Model.ID]=u;s.Names[u.Model.Name]=u.Model.ID;s.NextUser=max(s.NextUser,u.Model.ID);s.NextTheme=max(s.NextTheme,u.Theme.ID)
 case "icon":
  u:=s.Users[e.UID];u.Image=e.Image;u.Hash=hashImage(e.Image);s.NextIcon=max(s.NextIcon,e.ID)
 case "stream":
  d:=e.Stream; id:=d.Model.ID
  if d.Viewers==nil {d.Viewers=map[int64]int64{}};if d.Emoji==nil{d.Emoji=map[string]int64{}}
  s.Streams[id]=d;s.StreamIDs=append(s.StreamIDs,id);s.ByUser[d.Model.UserID]=append(s.ByUser[d.Model.UserID],id)
  for _,t:=range d.Tags{s.ByTag[t]=append(s.ByTag[t],id)};s.NextStream=max(s.NextStream,id)
  for i:=range s.Slots {v:=&s.Slots[i];if v.StartAt>=d.Model.StartAt&&v.EndAt<=d.Model.EndAt{v.Slot--}}
 case "comment":
  c:=*e.Comment;s.Comments[c.ID]=c;d:=s.Streams[c.LivestreamID];d.Comments=append(d.Comments,c.ID);d.Tips+=c.Tip;d.CommentCount++;d.MaxTip=max(d.MaxTip,c.Tip);s.TotalTip+=c.Tip;s.NextComment=max(s.NextComment,c.ID)
 case "reaction":
  r:=*e.Reaction;s.Reactions[r.ID]=r;d:=s.Streams[r.LivestreamID];d.Reactions=append(d.Reactions,r.ID);d.ReactionCount++;d.Emoji[r.EmojiName]++;s.NextReaction=max(s.NextReaction,r.ID)
 case "report":
  r:=*e.Report;s.Reports[r.ID]=r;s.Streams[r.LivestreamID].Reports=append(s.Streams[r.LivestreamID].Reports,r.ID);s.NextReport=max(s.NextReport,r.ID)
 case "ng":
  n:=*e.NG;d:=s.Streams[n.LivestreamID];d.NG=append(d.NG,n);s.NextNG=max(s.NextNG,n.ID)
  for _,id:=range e.Deleted {if c,ok:=s.Comments[id];ok {d.Tips-=c.Tip;d.CommentCount--;s.TotalTip-=c.Tip;delete(s.Comments,id)}}
  d.MaxTip=0;for _,id:=range d.Comments {if c,ok:=s.Comments[id];ok{d.MaxTip=max(d.MaxTip,c.Tip)}}
 case "enter":s.Streams[e.SID].Viewers[e.UID]++
 case "exit":delete(s.Streams[e.SID].Viewers,e.UID)
 }
}
func commit(e Event)error {
 b,err:=json.Marshal(e);if err!=nil{return err};b=append(b,'\n')
