 var err error
 defaultImage,err=os.ReadFile("../img/NoImage.jpg");if err!=nil{return err};defaultHash=hashImage(defaultImage)
 if err=os.MkdirAll(dataDir,0755);err!=nil{return err}
 f,err:=os.Open(filepath.Join(dataDir,"snapshot.gob"));if err!=nil{return err}
 state=newState();err=gob.NewDecoder(f).Decode(state);f.Close();if err!=nil{return err}
 wal,err=os.OpenFile(filepath.Join(dataDir,"wal.jsonl"),os.O_CREATE|os.O_RDWR,0644);if err!=nil{return err}
 r:=bufio.NewReader(wal);var offset int64
 for {b,er:=r.ReadBytes('\n');if er==io.EOF {if len(b)>0{if err=wal.Truncate(offset);err!=nil{return err}};break};if er!=nil{return er};var e Event;if err=json.Unmarshal(b,&e);err!=nil{return err};state.apply(e);offset+=int64(len(b))}
