  switch p{case "/api/user/:username":return s.user(id),200,nil;case "/api/user/:username/theme":return s.Users[id].Theme,200,nil;case "/api/user/:username/statistics":return s.userStats(id),200,nil;default:
   out:=make([]Livestream,0,len(s.ByUser[id]));for _,id:=range s.ByUser[id]{out=append(out,s.stream(id))};return out,200,nil}
